import os, glob, re

# Load grids from sessions file
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
G = {}

for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    header_str = match.group(1)
    if 'input' in header_str:
        # Parse: "Demo pair 1 input (15x15)" or "Test input (15x15)"
        demo_num = header_str.split()[1]
        h, w = int(match.group(2)), int(match.group(3))
        content = t[match.end():].split('\n')[:h]
        rows = [row.split() for row in content]
        for r_idx, row in enumerate(rows):
            if len(row) != w or not all(x.isdigit() for x in row):
                print(f"Warning: Bad row {r_idx}: {row}")
        grid = [[int(x) for x in row] for row in rows]
        if demo_num not in G:
            G[demo_num] = {'input': grid, 'header': header_str}
    elif 'output' in header_str:
        demo_num = header_str.split()[1]
        h, w = int(match.group(2)), int(match.group(3))
        content = t[match.end():].split('\n')[:h]
        rows = [row.split() for row in content]
        grid = [[int(x) for x in row] for row in rows]
        if demo_num in G:
            G[demo_num]['output'] = grid

for k, v in G.items():
    print(f"{k}: {v['header']}, input shape: {len(v['input'])}x{len(v['input'][0])}")

